import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor gemv_cute(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>

#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float warp_reduce_sum(float v) {
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1)
    v += __shfl_down_sync(0xffffffffu, v, offset);
  return v;
}

__device__ __forceinline__ float dot4(const float4& a, const float4& b) {
  return fmaf(a.x, b.x, fmaf(a.y, b.y, fmaf(a.z, b.z, a.w * b.w)));
}

// C = A * B, with A:(M,K) row-major, B:(K,1), C:(M,1)
// K is huge, M is small -> memory-bandwidth bound reduction over K.
// Split-K partitions the K reduction across gridDim.y slices so that many
// CTAs stream A concurrently; per-slice partials are combined with
// atomicAdd. Optimization (shared-memory-free streaming): the previous
// version staged A and B through shared memory with cp.async, but A has
// zero reuse and the ~20KB of shared memory per block capped theoretical
// occupancy at ~33% (shared-memory limited, per the profiler). Since the
// kernel is purely DRAM-bandwidth bound, this version streams A straight
// from global memory with evict-first float4 loads and per-thread
// unrolling for memory-level parallelism, so occupancy is register-
// limited instead of shared-memory-limited and far more global loads can
// be in flight per SM. B loads are warp-uniform (broadcast, L2-cached)
// and held in registers across the unrolled columns. CuTe tensors
// describe the global-memory views used by the streaming loop.
template <int Threads, int RowsPerBlock, int Unroll>
__global__ void __launch_bounds__(Threads)
gemv_cute_kernel(const float* __restrict__ A,
                 const float* __restrict__ B,
                 float* __restrict__ C,
                 int M, int K4, int K4_chunk)
{
  const int tid = threadIdx.x;
  const int m0  = blockIdx.x * RowsPerBlock;
  // [k4_begin, k4_end) is this split's slice of the float4 reduction range.
  const int k4_begin = blockIdx.y * K4_chunk;
  const int k4_end   = min(K4, k4_begin + K4_chunk);
  // A is streamed exactly once, so all loads use the evict-first policy.
  const float4* __restrict__ A4 = reinterpret_cast<const float4*>(A);
  const float4* __restrict__ B4 = reinterpret_cast<const float4*>(B);
  // CuTe views of the global operands: A rows and the B vector (in float4).
  Tensor gA = make_tensor(make_gmem_ptr(A4),
                          make_layout(make_shape(M, K4),
                                      make_stride((int64_t)K4, Int<1>{})));
  Tensor gB = make_tensor(make_gmem_ptr(B4),
                          make_layout(make_shape(K4),
                                      make_stride(Int<1>{})));
  // Clamp row indices so loads are always in-bounds; stores are guarded.
  int rows[RowsPerBlock];
  #pragma unroll
  for (int r = 0; r < RowsPerBlock; ++r) {
    int m = m0 + r;
    rows[r] = (m < M) ? m : (M - 1);
  }
  float acc[RowsPerBlock];
  #pragma unroll
  for (int r = 0; r < RowsPerBlock; ++r) acc[r] = 0.0f;
  // Stream this split's K slice with a two-stage register software
  // pipeline: the next super-tile's float4 loads are issued before the
  // FMAs of the current super-tile execute, so global-load latency
  // overlaps arithmetic and the number of independent loads in flight
  // per thread roughly doubles (register double-buffering).
  constexpr int SuperTile = Threads * Unroll;
  const int span  = k4_end - k4_begin;
  const int nfull = span / SuperTile;
  int base = k4_begin + tid;
  if (nfull > 0) {
    float4 bv0[Unroll], bv1[Unroll];
    float4 av0[RowsPerBlock][Unroll], av1[RowsPerBlock][Unroll];
    // Prologue: fill stage 0.
    #pragma unroll
    for (int u = 0; u < Unroll; ++u) bv0[u] = __ldcs(&gB(base + u * Threads));
    #pragma unroll
    for (int r = 0; r < RowsPerBlock; ++r) {
      const float4* arow = &gA(rows[r], base);
      #pragma unroll
      for (int u = 0; u < Unroll; ++u) av0[r][u] = __ldcs(arow + u * Threads);
    }
    for (int t = 0; t < nfull; ++t, base += SuperTile) {
      const int nb = base + SuperTile;
      if ((t & 1) == 0) {
        // Prefetch stage 1, then compute stage 0.
        if (t + 1 < nfull) {
          #pragma unroll
          for (int u = 0; u < Unroll; ++u) bv1[u] = __ldcs(&gB(nb + u * Threads));
          #pragma unroll
          for (int r = 0; r < RowsPerBlock; ++r) {
            const float4* arow = &gA(rows[r], nb);
            #pragma unroll
            for (int u = 0; u < Unroll; ++u) av1[r][u] = __ldcs(arow + u * Threads);
          }
        }
        #pragma unroll
        for (int r = 0; r < RowsPerBlock; ++r)
          #pragma unroll
          for (int u = 0; u < Unroll; ++u) acc[r] += dot4(av0[r][u], bv0[u]);
      } else {
        // Prefetch stage 0, then compute stage 1.
        if (t + 1 < nfull) {
          #pragma unroll
          for (int u = 0; u < Unroll; ++u) bv0[u] = __ldcs(&gB(nb + u * Threads));
          #pragma unroll
          for (int r = 0; r < RowsPerBlock; ++r) {
            const float4* arow = &gA(rows[r], nb);
            #pragma unroll
            for (int u = 0; u < Unroll; ++u) av0[r][u] = __ldcs(arow + u * Threads);
          }
        }
        #pragma unroll
        for (int r = 0; r < RowsPerBlock; ++r)
          #pragma unroll
          for (int u = 0; u < Unroll; ++u) acc[r] += dot4(av1[r][u], bv1[u]);
      }
    }
  }
  // Tail: fewer than SuperTile columns remain, guard each load.
  #pragma unroll
  for (int u = 0; u < Unroll; ++u) {
    const int c = base + u * Threads;
    if (c < k4_end) {
      const float4 bv = __ldcs(&gB(c));
      #pragma unroll
      for (int r = 0; r < RowsPerBlock; ++r)
        acc[r] += dot4(__ldcs(&gA(rows[r], c)), bv);
    }
  }
  // Block-level reduction per row (partial sum over this K slice).
  constexpr int NumWarps = Threads / 32;
  __shared__ float sdata[RowsPerBlock][NumWarps];
  const int lane = tid & 31;
  const int warp = tid >> 5;
  #pragma unroll
  for (int r = 0; r < RowsPerBlock; ++r) {
    float s = warp_reduce_sum(acc[r]);
    if (lane == 0) sdata[r][warp] = s;
  }
  __syncthreads();
  if (tid < 32) {
    #pragma unroll
    for (int r = 0; r < RowsPerBlock; ++r) {
      float v = (tid < NumWarps) ? sdata[r][tid] : 0.0f;
      v = warp_reduce_sum(v);
      if (tid == 0) {
        int m = m0 + r;
        if (m < M) atomicAdd(&C[m], v);
      }
    }
  }
}
torch::Tensor gemv_cute(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "A and B must be float32");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
  TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be 2D (K, 1)");
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  const int64_t M = A_c.size(0);
  const int64_t K = A_c.size(1);
  TORCH_CHECK(B_c.size(0) == K, "B.size(0) must equal A.size(1)");
  TORCH_CHECK(K % 4 == 0, "K must be divisible by 4 for vectorized loads");
  // Split-K accumulates partial sums via atomicAdd, so C must start at zero.
  auto C = torch::zeros({M, 1}, A_c.options());
  if (M == 0) return C;
  const int K4 = (int)(K >> 2);
  if (K4 == 0) return C;
  constexpr int Threads      = 128;
  constexpr int RowsPerBlock = 4;
  constexpr int Unroll       = 2;  // halved: double-buffered pipeline keeps MLP while capping register pressure
  constexpr int SplitK       = 8;
  // Round the per-split chunk up to a whole number of streaming super-tiles
  // so every split starts aligned to the Unroll x Threads column stride.
  const int stride = Threads * Unroll;
  int K4_chunk = (K4 + SplitK - 1) / SplitK;
  K4_chunk = ((K4_chunk + stride - 1) / stride) * stride;
  const int splits = (K4 + K4_chunk - 1) / K4_chunk;
  dim3 block(Threads);
  dim3 grid((unsigned)((M + RowsPerBlock - 1) / RowsPerBlock), (unsigned)splits);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemv_cute_kernel<Threads, RowsPerBlock, Unroll><<<grid, block, 0, stream>>>(
      A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
      (int)M, K4, K4_chunk);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gemv_cute launch failed: ",
              cudaGetErrorString(err));
  return C;
}
"""

gemv_ext = load_inline(
    name="gemv_cute_inline",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["gemv_cute"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
